window.KH_SURA(35, {"sura": "فاطر", "n": 35, "ayat": {"1": "الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ جَاعِلِ الْمَلَائِكَةِ رُسُلًا أُولِي أَجْنِحَةٍ مَثْنَى وَثُلَاثَ وَرُبَاعَ يَزِيدُ فِي الْخَلْقِ مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "2": "مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُ مِنْ بَعْدِهِ وَهُوَ الْعَزِيزُ الْحَكِيمُ", "3": "يَاأَيُّهَا النَّاسُ اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ هَلْ مِنْ خَالِقٍ غَيْرُ اللَّهِ يَرْزُقُكُمْ مِنَ السَّمَاءِ وَالْأَرْضِ لَا إِلَهَ إِلَّا هُوَ فَأَنَّى تُؤْفَكُونَ", "4": "وَإِنْ يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ", "5": "يَاأَيُّهَا النَّاسُ إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلَا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ", "6": "إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُو حِزْبَهُ لِيَكُونُوا مِنْ أَصْحَابِ السَّعِيرِ", "7": "الَّذِينَ كَفَرُوا لَهُمْ عَذَابٌ شَدِيدٌ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", "8": "أَفَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ فَرَآهُ حَسَنًا فَإِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍ إِنَّ اللَّهَ عَلِيمٌ بِمَا يَصْنَعُونَ", "9": "وَاللَّهُ الَّذِي أَرْسَلَ الرِّيَاحَ فَتُثِيرُ سَحَابًا فَسُقْنَاهُ إِلَى بَلَدٍ مَيِّتٍ فَأَحْيَيْنَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا كَذَلِكَ النُّشُورُ", "10": "مَنْ كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ وَالَّذِينَ يَمْكُرُونَ السَّيِّئَاتِ لَهُمْ عَذَابٌ شَدِيدٌ وَمَكْرُ أُولَئِكَ هُوَ يَبُورُ", "11": "وَاللَّهُ خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَاجًا وَمَا تَحْمِلُ مِنْ أُنْثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ وَمَا يُعَمَّرُ مِنْ مُعَمَّرٍ وَلَا يُنْقَصُ مِنْ عُمُرِهِ إِلَّا فِي كِتَابٍ إِنَّ ذَلِكَ عَلَى اللَّهِ يَسِيرٌ", "12": "وَمَا يَسْتَوِي الْبَحْرَانِ هَذَا عَذْبٌ فُرَاتٌ سَائِغٌ شَرَابُهُ وَهَذَا مِلْحٌ أُجَاجٌ وَمِنْ كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا وَتَرَى الْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا مِنْ فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ", "13": "يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُسَمًّى ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ", "14": "إِنْ تَدْعُوهُمْ لَا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ", "15": "يَاأَيُّهَا النَّاسُ أَنْتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ", "16": "إِنْ يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ", "17": "وَمَا ذَلِكَ عَلَى اللَّهِ بِعَزِيزٍ", "18": "وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى وَإِنْ تَدْعُ مُثْقَلَةٌ إِلَى حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَيْءٌ وَلَوْ كَانَ ذَا قُرْبَى إِنَّمَا تُنْذِرُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ وَأَقَامُوا الصَّلَاةَ وَمَنْ تَزَكَّى فَإِنَّمَا يَتَزَكَّى لِنَفْسِهِ وَإِلَى اللَّهِ الْمَصِيرُ", "19": "وَمَا يَسْتَوِي الْأَعْمَى وَالْبَصِيرُ", "20": "وَلَا الظُّلُمَاتُ وَلَا النُّورُ", "21": "وَلَا الظِّلُّ وَلَا الْحَرُورُ", "22": "وَمَا يَسْتَوِي الْأَحْيَاءُ وَلَا الْأَمْوَاتُ إِنَّ اللَّهَ يُسْمِعُ مَنْ يَشَاءُ وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ", "23": "إِنْ أَنْتَ إِلَّا نَذِيرٌ", "24": "إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا وَإِنْ مِنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ", "25": "وَإِنْ يُكَذِّبُوكَ فَقَدْ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ جَاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّنَاتِ وَبِالزُّبُرِ وَبِالْكِتَابِ الْمُنِيرِ", "26": "ثُمَّ أَخَذْتُ الَّذِينَ كَفَرُوا فَكَيْفَ كَانَ نَكِيرِ", "27": "أَلَمْ تَرَ أَنَّ اللَّهَ أَنْزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِ ثَمَرَاتٍ مُخْتَلِفًا أَلْوَانُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ وَحُمْرٌ مُخْتَلِفٌ أَلْوَانُهَا وَغَرَابِيبُ سُودٌ", "28": "وَمِنَ النَّاسِ وَالدَّوَابِّ وَالْأَنْعَامِ مُخْتَلِفٌ أَلْوَانُهُ كَذَلِكَ إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ إِنَّ اللَّهَ عَزِيزٌ غَفُورٌ", "29": "إِنَّ الَّذِينَ يَتْلُونَ كِتَابَ اللَّهِ وَأَقَامُوا الصَّلَاةَ وَأَنْفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَارَةً لَنْ تَبُورَ", "30": "لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُمْ مِنْ فَضْلِهِ إِنَّهُ غَفُورٌ شَكُورٌ", "31": "وَالَّذِي أَوْحَيْنَا إِلَيْكَ مِنَ الْكِتَابِ هُوَ الْحَقُّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ إِنَّ اللَّهَ بِعِبَادِهِ لَخَبِيرٌ بَصِيرٌ", "32": "ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ مُقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ", "33": "جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ", "34": "وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ", "35": "الَّذِي أَحَلَّنَا دَارَ الْمُقَامَةِ مِنْ فَضْلِهِ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ", "36": "وَالَّذِينَ كَفَرُوا لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا كَذَلِكَ نَجْزِي كُلَّ كَفُورٍ", "37": "وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَا أَخْرِجْنَا نَعْمَلْ صَالِحًا غَيْرَ الَّذِي كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُمْ مَا يَتَذَكَّرُ فِيهِ مَنْ تَذَكَّرَ وَجَاءَكُمُ النَّذِيرُ فَذُوقُوا فَمَا لِلظَّالِمِينَ مِنْ نَصِيرٍ", "38": "إِنَّ اللَّهَ عَالِمُ غَيْبِ السَّمَاوَاتِ وَالْأَرْضِ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ", "39": "هُوَ الَّذِي جَعَلَكُمْ خَلَائِفَ فِي الْأَرْضِ فَمَنْ كَفَرَ فَعَلَيْهِ كُفْرُهُ وَلَا يَزِيدُ الْكَافِرِينَ كُفْرُهُمْ عِنْدَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ الْكَافِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا", "40": "قُلْ أَرَأَيْتُمْ شُرَكَاءَكُمُ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللَّهِ أَرُونِي مَاذَا خَلَقُوا مِنَ الْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِي السَّمَاوَاتِ أَمْ آتَيْنَاهُمْ كِتَابًا فَهُمْ عَلَى بَيِّنَتٍ مِنْهُ بَلْ إِنْ يَعِدُ الظَّالِمُونَ بَعْضُهُمْ بَعْضًا إِلَّا غُرُورًا", "41": "إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَنْ تَزُولَا وَلَئِنْ زَالَتَا إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِنْ بَعْدِهِ إِنَّهُ كَانَ حَلِيمًا غَفُورًا", "42": "وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِنْ جَاءَهُمْ نَذِيرٌ لَيَكُونُنَّ أَهْدَى مِنْ إِحْدَى الْأُمَمِ فَلَمَّا جَاءَهُمْ نَذِيرٌ مَا زَادَهُمْ إِلَّا نُفُورًا", "43": "اسْتِكْبَارًا فِي الْأَرْضِ وَمَكْرَ السَّيِّئِ وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ فَهَلْ يَنْظُرُونَ إِلَّا سُنَّتَ الْأَوَّلِينَ فَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَبْدِيلًا وَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَحْوِيلًا", "44": "أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ وَكَانُوا أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِنْ شَيْءٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ إِنَّهُ كَانَ عَلِيمًا قَدِيرًا", "45": "وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلَى ظَهْرِهَا مِنْ دَابَّةٍ وَلَكِنْ يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا"}, "units": [{"aya": 1, "title": "في علة ترك إجراء مثنى وثلاث ورباع، وهى ترجمة عن أجنحة، وأجنحة نكرة", "tabari": {"page": "19/326", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "ترك إجراؤهن؛ لأنهن مصروفات عن وجوههن، وذلك أن ﴿مثنى﴾ مصروف عن اثنين، ﴿وثلاث﴾ عن ثلاثة، ﴿ورباع﴾ عن أربعة، فصرن نظير عمر، وزفر، إذ صرف هذا عن عامر، إلى عمر، وهذا عن زافر إلى زفر، وأنشد بعضهم في ذلك :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "لم يصرف ذلك؛ لأنه يوهم به الثلاثة والأربعة. قال: وهذا لا يستعمل إلا في حال العدد. وقال بعض نحويى الكوفة: هن مصروفات عن المعارف؛ لأن الألف واللام لا تدخلها، والإضافة لا تدخلها. قال: ولو دخلتها الإضافة والألف واللام، لكانت نكرة، وهى ترجمة عن النكرة . قال: وكذلك ما كان في القرآن، بمثله : ﴿أن تقوموا لله مثنى وفرادى﴾. [سبأ: ٤٦]. وكذلك وحاد وأحاد، وما أشبهه من مصروف العدد", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "في معنى قوله: ﴿من كان يريد العزة فلله العزة جميعا﴾", "tabari": {"page": "19/337", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك: من كان يريد العزة بعبادة الآلهة والأوثان، فإن العزة لله جميعا", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [63852, 63864, 63885]}, {"n": 2, "t": "معنى ذلك: من كان يريد العزة فليتعزز بطاعة الله", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [63854, 63874, 63875, 63876, 63887]}, {"n": 3, "t": "بل معنى ذلك: من كان يريد علم العزة لمن هي؟ فإنها لله جميعا كلها، أي: كل وجه من العزة فلله", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5359, "mi": 1, "aya": 10, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 337", "qawl": "الأول", "nass": "لأن الآيات التي قبل هذه الآية جرت بتقريع الله المشركين على عبادتهم الأوثان، وتوبيخه إياهم، ووعيده لهم عليها، فأولى بهذه أيضا أن تكون من جنس الحث على فراق ذلك، فكانت قصتها شبيهة بقصتها، وكانت في سياقها", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5359, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 205", "qawl": "الأول", "nass": "وهذا تمسك بقوله تعالى: {واتخذوا من دون الله آلهة ليكونوا لهم عزا} [مريم: 81]", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["035_001_1.png"], "pages": [427], "n": 3, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5359, "masala": "معنى: {من كان يريد العزة فلله العزة جميعا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "من كان يريد العزة بعبادة الآلهة والأوثان فإن العزة لله جميعا", "ashab": "", "athar": []}, {"n": 2, "t": "من كان يريد العزة فليتعزز بطاعة الله", "ashab": "", "athar": []}, {"n": 3, "t": "من كان يريد علم العزة لمن هي فإنها لله جميعا كلها، أي: كل وجه من العزة فلله", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]], "2": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]], "2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 10, "title": "هاء الكناية في قوله تعالى: {يرفعه}", "mawsua": {"taliq": 5362, "masala": "هاء الكناية في قوله تعالى: {يرفعه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها ترجع إلى العمل الصالح، والمعنى: والعمل الصالح يرفعه الكلم الطيب", "ashab": "", "athar": []}, {"n": 2, "t": "أنها ترجع إلى الكلم الطيب، والمعنى: والعمل الصالح يرفع الكلم الطيب", "ashab": "", "athar": []}, {"n": 3, "t": "أنها ترجع إلى الله عز وجل، والمعنى: والعمل الصالح يرفعه الله إليه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5362, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 206", "qawl": "الثالث", "nass": "وهذا أرجح الأقوال", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {"3": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 11, "title": "في تأويل ذلك ﴿وما يعمر من معمر ولا ينقص من عمره إلا في كتاب﴾", "tabari": {"page": "19/342", "sarih": 1, "tarjih": "وأولى التأويلين في ذلك عندى بالصواب التأويل الأول، وذلك أن ذلك هو أظهر معنييه، وأشبههما بظاهر التنزيل.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "معناه: وما يعمر من معمر فيطول عمره، ولا ينقص من عمر آخر غيره عن عمر هذا الذي عمر عمرا طويلا، ﴿إلا في كتاب﴾ عنده مكتوب قبل أن تحمل به أمه، وقبل أن تضعه، قد أحصى ذلك كله، وعلمه قبل أن يخلقه، لا يزاد فيما كتب له ولا ينقص", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [63898, 63899, 63900, 63919, 63920]}, {"n": 2, "t": "بل معنى ذلك: وما يعمر من معمر ولا ينقص من عمره، بفناء ما فنى من أيام حياته، فذلك هو نقصان عمره. والهاء على هذا التأويل للمعمر الأول؛ لأن معنى الكلام: ما يطول عمر أحد، ولا يذهب من عمره شيء فينقص، إلا وهو في كتاب عند الله مكتوب، قد [أحصاه وعلمه]", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "19/ 344", "qawl": "الأول", "nass": "فالهاء التي في قوله: {ولا ينقص من عمره} على هذا التأويل -وإن كانت في الظاهر أنها كناية عن اسم المعمر الأول- فهي كناية اسم آخر غيره، وإنما حسن ذلك لأن صاحبها لو أظهر أظهر بلفظ الأول، وذلك كقولهم: عندي ثوب ونصفه، والمعنى: ونصف الآخر", "qawaid": [], "tabi": ""}, {"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "7/ 207", "qawl": "", "nass": "أي: أن القول تضمن شخصين، يعمر أحدهما مائة سنة أو نحوها، وينقص من الآخر بأن يكون عاما واحدا أو نحوه … لكنه أعاد الضمير إيجازا واختصارا، والبيان التام أن يقول: ولا ينقص من عمر معمر. لأن لفظ", "qawaid": [], "tabi": ""}, {"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "", "qawl": "الثاني", "nass": "والهاء على هذا التأويل للمعمر الأول؛ لأن معنى الكلام: ما يطول عمر أحد، ولا يذهب من عمره شيء فينقص، إلا وهو في كتاب عند الله مكتوب، قد أحصاه وعلمه", "qawaid": [], "tabi": ""}, {"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "7/ 208", "qawl": "", "nass": "أي: ما يعمر إنسان ولا ينقص من عمره، بأن يحصى ما مضى منه، إذا مر حول كتب ذلك، ثم حول. فهذا هو النقص", "qawaid": [], "tabi": ""}, {"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 345", "qawl": "الأول", "nass": "أظهر معنييه، وأشبههما بظاهر التنزيل", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "أي: لا يخترم بسبب قدرة الله تعالى، ولو شاء لأخر ذلك السبب، وروي أنه قال حين طعن عمر?: لو دعا الله لزاد في أجله. فأنكر عليه المسلمون ذلك، وقالوا: إن الله تعالى يقول: {فإذا جاء أجلهم لا يستأخرون ساعة} [الأعراف: 34]. فاحتج بهذه الآية", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5365, "mi": 1, "aya": 11, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 303", "qawl": "", "nass": "أن الله يكتب للعبد أجلا في صحف الملائكة، فإذا وصل رحمه زاد في ذلك المكتوب، وإن عمل ما يوجب النقص نقص من ذلك المكتوب. ونظير هذا ما في الترمذي وغيره عن النبي صلى الله عليه وسلم: «أن آدم لما طلب من الله أن يريه صورة الأنبياء من ذريته فأراه إياهم، فرأى فيهم رجلا له بصيص، فقال: من هذا، يا رب؟ فقال: ابنك داود. قال: فكم عمره؟ قال: أربعون سنة. قال: وكم عمري؟ قال: ألف سنة. قال: فقد وهبت له من عمري ستين سنة. فكتب عليه كتاب، وشهدت عليه الملائكة، فلما حضرته الوفاة قال: قد بقي من عمري ستون سنة. قالوا: وهبتها لابنك داود. فأنكر ذلك، فأخرجوا الكتاب. قال النبي صلى الله عليه وسلم: فنسي آدم فنسيت ذريته، وجحد آدم فجحدت ذريته", "qawaid": ["القرآن والنظائر"], "tabi": ""}], "mushid": {"i": 2, "imgs": ["035_002_1.png"], "pages": [427], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5365, "masala": "معنى: {وما يعمر من معمر ولا ينقص من عمره إلا في كتاب}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المعنى: وما يعمر من معمر ولا ينقص من عمر آخر غيره إلا في كتاب", "ashab": "", "athar": []}, {"n": 2, "t": "وما يعمر من معمر ولا ينقص من عمره بفناء ما فني من أيام حياته إلا في كتاب", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "w"], ["ابن جرير", "r"]], "2": [["ابن جرير", "w"]]}, "t": {"1": [["ابن جرير", "w"], ["ابن جرير", "r"]], "2": [["ابن جرير", "w"]]}, "gen": [["ابن تيمية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"], "ابن تيمية": ["القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 14, "title": "قوله تعالى: {يكفرون}", "mawsua": {"taliq": 5369, "masala": "قوله تعالى: {يكفرون}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون بكلام وعبارة يقدر الله الأصنام عليها، ويخلق لها إدراكا يقتضيها", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون بما يظهر هناك من جمودها وبطولها عند حركة كل ناطق، ومدافعة كل محتج", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5369, "mi": 1, "aya": 14, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 210 - 211", "qawl": "", "nass": "أن يكون بكلام وعبارة يقدر الله الأصنام عليها، ويخلق لها إدراكا يقتضيها", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 27, "title": "معنى: {كذلك}", "mawsua": {"taliq": 5376, "masala": "معنى: {كذلك}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون من الكلام الأول", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون من الكلام الثاني يخرج مخرج السبب", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5376, "mi": 1, "aya": 27, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 216", "qawl": "", "nass": "أن يكون من الكلام الأول", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 32, "title": "في معنى الكتاب الذي ذكر الله في هذه الآية أنه أورثه الذين اصطفاهم من عباده، ومن المصطفون من عباده، والظالم لنفسه", "tabari": {"page": "19/367", "sarih": 1, "tarjih": "وأولى الأقوال في تأويل ذلك بالصواب: تأويل من قال: عنى بقوله: ﴿ثم أورثنا الكتاب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه﴾. الكتب التي أنزلت من قبل الفرقان.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "الكتاب هو الكتب التي أنزلها الله من قبل الفرقان، والمصطفون من عباده أمة محمد، والظالم لنفسه أهل الإجرام منهم", "taqdim": 0, "n_athar": 8, "qailun": [["ابن عباس", "صحابي"], ["عبد الله بن مسعود", "صحابي"], ["كعب", "صحابي"], ["قوله تعالى", ""]], "athar": [64085, 64091, 64092, 64093, 64094, 64095, 64096, 64097, 64099, 64100, 64102, 64104]}, {"n": 2, "t": "الكتاب الذي أورث هؤلاء القوم، هو شهادة أن لا إله إلا الله، والمصطفون هم أمة محمد ﷺ، والظالم لنفسه منهم هو المنافق، وهو في النار، والمقتصد والسابق بالخيرات في الجنة", "taqdim": 0, "n_athar": 11, "qailun": [["عبد الله", "صحابي"], ["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["عوف", ""], ["قتادة", "تابعي"], ["الضحاك", "تابعي"], ["الأعمش", "تابع التابعين"], ["في هذه الآية", ""]], "athar": [64075, 64084, 64085, 64091, 64092, 64093, 64094, 64095, 64096, 64097, 64099, 64110, 64111, 64112, 64113, 64115, 64116, 64121, 64123, 64124, 64132]}]}, "mawaqif": [{"taliq": 5381, "mi": 1, "aya": 32, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 373 - 374", "qawl": "الأول", "nass": "لأن الله -جل ثناؤه- قال لنبيه محمد صلى الله عليه وسلم: {والذي أوحينا إليك من الكتاب هو الحق مصدقا لما بين يديه}، ثم أتبع ذلك قوله: {ثم أورثنا الكتاب الذين اصطفينا}، فكان معلوما -إذ كان معنى الميراث إنما هو انتقال معنى من قوم إلى آخرين، ولم تكن أمة على عهد نبينا صلى الله عليه وسلم انتقل إليهم كتاب من قوم كانوا قبلهم غير أمته- أن ذلك معناه. وإذ كان ذلك كذلك فبين أن المصطفين من عباده هم مؤمنو أمته؛ وأما الظالم لنفسه فإنه لأن يكون من أهل الذنوب والمعاصي -التي هي دون النفاق والشرك عندي- أشبه بمعنى الآية من أن يكون المنافق أو الكافر، وذلك أن الله -تعالى ذكره- أتبع هذه الآية قوله: {جنات عدن يدخلونها}، فعم بدخول الجنة جميع الأصناف الثلاثة", "qawaid": ["السياق", "اللغة", "الدلالة العقلية", "السنة"], "tabi": ""}, {"taliq": 5381, "mi": 1, "aya": 32, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 311 - 312", "qawl": "", "nass": "", "qawaid": ["ظاهر الآية ولفظها", "السنة", "السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5381, "mi": 1, "aya": 32, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "11/ 323", "qawl": "", "nass": "", "qawaid": ["ظاهر الآية ولفظها", "السنة", "السياق", "الدلالة العقلية"], "tabi": "ابن تيمية"}, {"taliq": 5381, "mi": 1, "aya": 32, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "والصحيح أن الظالم لنفسه من هذه الأمة، وهذا اختيار ابن جرير كما هو ظاهر الآية، وكما جاءت به الأحاديث عن رسول الله صلى الله عليه وسلم من طرق يشد بعضها بعضا …", "qawaid": [], "tabi": ""}, {"taliq": 5381, "mi": 1, "aya": 32, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "فهذه الآثار يشد بعضها بعضا، وأنها قد تعددت طرقها واختلفت مخارجها، وسياق الآية يشهد لها بالصحة فلا تعدل عنها", "qawaid": [], "tabi": ""}, {"taliq": 5381, "mi": 1, "aya": 32, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "الجامع", "nass": "أن الظالم لنفسه: هو المفرط بترك مأمور أو فعل محظور. والمقتصد: القائم بأداء الواجبات وترك المحرمات، والسابق بالخيرات: بمنزلة المقرب الذي يتقرب إلى الله بالنوافل بعد الفرائض حتى يحبه الحق", "qawaid": [], "tabi": ""}], "mushid": {"i": 3, "imgs": ["035_003_1.png"], "pages": [428], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5381, "masala": "معنى الكتاب الموروث، وفي المراد بالمصطفين من عباد الله، وفي المراد بالظالم لنفسه", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الكتاب: ما أنزله الله من الكتب قبل الفرقان. والمصطفين من عباده: أمة محمد صلى الله عليه وسلم. والظالم لنفسه: أهل الإجرام منهم", "ashab": "", "athar": []}, {"n": 2, "t": "أن الكتاب: هو شهادة أن لا إله إلا الله. والمصطفين: هم أمة محمد صلى الله عليه وسلم. والظالم لنفسه منهم: هو المنافق، وهو في النار؛ والمقتصد والسابق بالخيرات في الجنة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [["ابن تيمية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["السياق", "اللغة", "الدلالة العقلية", "السنة"], "ابن تيمية": ["ظاهر الآية ولفظها", "السنة", "السياق", "الدلالة العقلية"], "ابن كثير": ["ظاهر الآية ولفظها", "السنة", "السياق", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 34, "title": "في الحزن الذي حمد الله على إذهابه عنهم هؤلاء القوم", "tabari": {"page": "19/377", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله تعالى ذكره أخبر عن هؤلاء القوم الذين أكرمهم بما أكرمهم به، أنهم قالوا حين دخلوا الجنة: ﴿الحمد لله الذي أذهب عنا الحزن﴾. وخوف دخول النار من الحزن، والجزع من الموت من الحزن، والجزع من الحاجة إلى المطعم من الحزن، ولم يخصص الله إذ أخبر عنهم أنهم حمدوه على إذهابه الحزن عنهم، نوعا دون نوع، بل أخبر عنهم أنهم عموا جميع أنواع الحزن بقولهم ذلك، وكذلك ذلك؛ لأن من دخل الجنة فلا حزن عليه بعد ذلك، فحمدهم الله على إذهابه عنهم جميع معاني الحزن.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك الحزن الذي كانوا فيه قبل دخولهم الجنة من خوف النار، إذ كانوا خائفين أن يدخلوها", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["الحسن", "تابعي"]], "athar": [64150, 64151, 64158]}, {"n": 2, "t": "عنى به الموت", "taqdim": 0, "n_athar": 1, "qailun": [["عطية", "تابعي"]], "athar": [64159]}, {"n": 3, "t": "عنى به حزن الخبز", "taqdim": 0, "n_athar": 1, "qailun": [["شمر", ""]], "athar": [64148, 64164, 64165, 64170]}, {"n": 4, "t": "عنى بذلك الحزن من التعب الذي كانوا فيه في الدنيا", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [64161, 64162, 64169]}, {"n": 5, "t": "بل عنى بذلك الحزن الذي ينال الظالم لنفسه في موقف القيامة", "taqdim": 0, "n_athar": 1, "qailun": [["الأعمش", "تابع التابعين"]], "athar": []}]}, "mawaqif": [{"taliq": 5383, "mi": 1, "aya": 34, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 379", "qawl": "العموم", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله -تعالى ذكره- أخبر عن هؤلاء القوم الذين أكرمهم بما أكرمهم به، أنهم قالوا حين دخلوا الجنة: {الحمد لله الذي أذهب عنا الحزن}. وخوف دخول النار من الحزن، والجزع من الموت من الحزن، والجزع من الحاجة إلى المطعم من الحزن، ولم يخصص الله -إذ أخبر عنهم أنهم حمدوه على إذهابه الحزن عنهم- نوعا دون نوع، بل أخبر عنهم أنهم عموا جميع أنوع الحزن بقولهم ذلك، وكذلك ذلك؛ لأن من دخل الجنة فلا حزن عليه بعد ذلك، فحمدهم الله على إذهابه عنهم جميع معاني الحزن", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 5383, "mi": 1, "aya": 34, "alam": "ابن عطية", "fil": "ووافقه", "kind": "موافقة", "ref": "7/ 222", "qawl": "", "nass": "و {الحزن} في هذه الآية عام في جميع الأحزان", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 4, "imgs": ["035_004_1.png"], "pages": [428], "n": 5, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5383, "masala": "معنى: {الحزن}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "عني به خوف النار", "ashab": "", "athar": []}, {"n": 2, "t": "أنه حزن الموت", "ashab": "", "athar": []}, {"n": 3, "t": "حزن الجوع", "ashab": "", "athar": []}, {"n": 4, "t": "أنه التعب الذي كانوا فيه في الدنيا", "ashab": "", "athar": []}, {"n": 5, "t": "أنه الذي ينال الظالم لنفسه في موقف القيامة", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"], ["ابن عطية", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 37, "title": "في مبلغ ذلك ﴿أولم نعمركم ما يتذكر فيه من تذكر﴾", "tabari": {"page": "19/384", "sarih": 1, "tarjih": "وأشبه القولين بتأويل الآية، إذ كان الخبر الذي ذكرناه عن رسول الله ﷺ خبرا في إسناده بعض من يجب التثبت في نقله - قول من قال: ذلك أربعون سنة؛ لأن في الأربعين يتناهى عقل الإنسان وفهمه، وما قبل ذلك وما بعده، منتقص عن كماله في حال الأربعين.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "ذلك أربعون سنة", "taqdim": 0, "n_athar": 2, "qailun": [["مسروق", "تابعي"]], "athar": [64203]}, {"n": 2, "t": "بل ذلك ستون سنة", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["رسول الله", ""], ["أبي هريرة", "صحابي"]], "athar": [64196, 64197, 64199, 64200, 64201, 64202, 64211]}]}, "mawaqif": [{"taliq": 5384, "mi": 1, "aya": 37, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 224", "qawl": "الأول", "nass": "وهذا قول حسن، ورويت فيه آثار", "qawaid": [], "tabi": ""}, {"taliq": 5384, "mi": 1, "aya": 37, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 386 - 387 بتصرف", "qawl": "الأول", "nass": "وأشبه القولين بتأويل الآية قول من قال: ذلك أربعون سنة؛ لأن في الأربعين يتناهى عقل الإنسان وفهمه، وما قبل ذلك وما بعده منتقص عن كماله في حال الأربعين", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5384, "mi": 1, "aya": 37, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 332", "qawl": "الثاني", "nass": "فهذه الرواية أصح عن ابن عباس، وهي الصحيحة في نفس الأمر أيضا، لما ثبت في ذلك من الحديث كما سنورده …", "qawaid": ["السنة"], "tabi": ""}, {"taliq": 5384, "mi": 1, "aya": 37, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 223 - 224", "qawl": "", "nass": "البلوغ", "qawaid": [], "tabi": ""}], "mushid": {"i": 5, "imgs": ["035_005_1.png"], "pages": [428], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5384, "masala": "مقدار التعمير في قوله تعالى: {أولم نعمركم ما يتذكر فيه من تذكر}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أربعون سنة", "ashab": "", "athar": []}, {"n": 2, "t": "ستون سنة", "ashab": "", "athar": []}, {"n": 3, "t": "ثماني عشر سنة", "ashab": "", "athar": []}, {"n": 4, "t": "ست وأربعون", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]], "2": [["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"]], "2": [["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"], "ابن كثير": ["السنة"]}, "rulesD": {}}}, {"aya": 37, "title": "في معنى النذير", "tabari": {"page": "19/387", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى به محمدا ﷺ", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [64216]}, {"n": 2, "t": "عنى به الشيب", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5385, "mi": 1, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 225", "qawl": "", "nass": "في قول الجمهور: الأنبياء، كل نبي نذير أمته ومعاصريه، ومحمد صلى الله عليه وسلم نذير العالم في غابر الزمن", "qawaid": [], "tabi": ""}, {"taliq": 5385, "mi": 1, "aya": 37, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 336", "qawl": "الأول", "nass": "وهو الأظهر؛ لقوله تعالى: {ونادوا يامالك ليقض علينا ربك قال إنكم ماكثون * لقد جئناكم بالحق ولكن أكثركم للحق كارهون} [الزخرف: 77 - 78]، أي: لقد بينا لكم الحق على ألسنة الرسل، فأبيتم وخالفتم، وقال تعالى: {وما كنا معذبين حتى نبعث رسولا} [الإسراء: 15]، وقال تبارك وتعالى: {كلما ألقي فيها فوج سألهم خزنتها ألم يأتكم نذير * قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء إن أنتم إلا في ضلال كبير} [الملك: 8 - 9]", "qawaid": ["القرآن والنظائر"], "tabi": ""}], "mushid": {"i": 6, "imgs": ["035_006_1.png"], "pages": [428], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5385, "masala": "معنى: {النذير}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه النبي صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الشيب", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن كثير": ["القرآن والنظائر"]}, "rulesD": {}}}], "extra": [], "others": {"1": [{"id": 5357, "kinds": "توجيه،نقل", "text": "وجَّه ابنُ عطية (7/ 202) قول ابن عباس، وابن شهاب الزهري، وقتادة بقوله: «وإنما ذَكَر هذه الأشياء من ذَكَرها على جهة المثال، لا أن المقصود هي فقط، وإنما مثلوا بأشياء هي زيادات خارجة عن الغالب المعتاد الموجود كثيرًا».", "mawaqif": [{"taliq": 5357, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 202", "qawl": "ابن عباس", "nass": "وإنما ذكر هذه الأشياء من ذكرها على جهة المثال، لا أن المقصود هي فقط، وإنما مثلوا بأشياء هي زيادات خارجة عن الغالب المعتاد الموجود كثيرا", "qawaid": [], "tabi": ""}]}], "5": [{"id": 5358, "kinds": "توجيه", "text": "لم يذكر ابنُ جرير (19/ 331) في معنى: {ولا يَغُرَّنَّكُمْ بِاللَّهِ الغَرُورُ} سوى قول ابن عباس.\nووجَّه ابنُ كثير (11/ 306) قول ابن عباس بقوله: «أي: لا يفتنَنَّكم الشيطان ويصرفنَّكم عن اتباع رسل الله وتصديق كلماته؛ فإنه غرّار كذّاب أفّاك».", "mawaqif": [{"taliq": 5358, "mi": 0, "aya": 5, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "11/ 306", "qawl": "ابن عباس", "nass": "أي: لا يفتننكم الشيطان ويصرفنكم عن اتباع رسل الله وتصديق كلماته؛ فإنه غرار كذاب أفاك", "qawaid": [], "tabi": ""}]}], "10": [{"id": 5360, "kinds": "نقد،نقل", "text": "انتقد ابنُ عطية (7/ 206) قول ابن عباس من جهةِ ثبوته، ومخالفته اعتقاد أهل الحق، فقال: «وهذا قولٌ يردُّه معتقد أهل الحق والسنة، ولا يصح عن ابن عباس رضي الله عنهما، والحق أن العاصي التارك للفرائض إذا ذكر الله تعالى وقال كلامًا طيِّبًا فإنه مكتوبٌ له، مُتَقَبَّلٌ منه، وله حسناته، وعليه سيئاته، والله تعالى يتقبَّل مِن كل مَن اتقى الشرك، وأيضًا فإن الكَلِم الطَّيِّب عملٌ صالح». غير أنه التمس له وجْهًا يمكن أن يُصَحَّح عليه، فقال: «وإنما يستقيم قول من يقول: إن العمل هو الرافعُ للكَلِم. بأن يُتَأَوَّل أنه يزيد في رفْعِه وحُسْنِ موقعه إذا تعاضد معه، كما أن صاحب الأعمال من صلاة وصيام وغير ذلك إذا تخلَّل أعماله كلمٌ طيِّبٌ وذكر لله كانت الأعمال أشرف، فيكون قوله: {والعَمَلُ الصّالِحُ يَرْفَعُهُ} موعظةً وتذكرةً وحضًّا على الأعمال».", "mawaqif": [{"taliq": 5360, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 206", "qawl": "ابن عباس", "nass": "وهذا قول يرده معتقد أهل الحق والسنة، ولا يصح عن ابن عباس رضي الله عنهما، والحق أن العاصي التارك للفرائض إذا ذكر الله تعالى وقال كلاما طيبا فإنه مكتوب له، متقبل منه، وله حسناته، وعليه سيئاته، والله تعالى يتقبل من كل من اتقى الشرك، وأيضا فإن الكلم الطيب عمل صالح", "qawaid": [], "tabi": ""}]}, {"id": 5361, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (11/ 310) هذا الأثر من رواية ابن جرير بسنده عن يعقوب بن إبراهيم، عن ابن علية، عن سعيد الجريري، عن عبد الله بن شقيق، عن كعب الأحبار، ثم علَّق عليه بقوله: «وهذا إسناد صحيح إلى كعب الأحبار، وقد روي مرفوعًا».", "mawaqif": [{"taliq": 5361, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 310", "qawl": "", "nass": "وهذا إسناد صحيح إلى كعب الأحبار، وقد روي مرفوعا", "qawaid": [], "tabi": ""}]}, {"id": 5363, "kinds": "ترجيح،توجيه،تعليق،نقل", "text": "نقل ابنُ عطية (7/ 207) عن بعض المفسرين أنّ قوله تعالى: {والَّذِينَ يَمْكُرُونَ السَّيِّئاتِ} يدخل فيها أهل الرياء. ثم علَّق عليه بقوله: «ونزول الآية أولًا في المشركين».\nووجَّه ابنُ كثير (11/ 311) قول مجاهد، وسعيد بن جبير، وشهر بن حوشب: أنهم المراءون بأعمالهم، بقوله: «يعني: يمكرون بالناس، يوهمون أنهم في طاعة الله، وهم بغضاء إلى الله عز وجل، يراءون بأعمالهم، {ولا يَذْكُرُونَ اللَّهَ إلا قَلِيلا} [النساء: 142]». ورجَّح مستندًا إلى دلالة العموم شمول معنى الآية، فقال: «والصحيح أنها عامة، والمشركون داخلون بطريق الأَوْلى».", "mawaqif": [{"taliq": 5363, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 207", "qawl": "", "nass": "ونزول الآية أولا في المشركين", "qawaid": [], "tabi": ""}, {"taliq": 5363, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "11/ 311", "qawl": "مجاهد", "nass": "يعني: يمكرون بالناس، يوهمون أنهم في طاعة الله، وهم بغضاء إلى الله عز وجل، يراءون بأعمالهم، {ولا يذكرون الله إلا قليلا} [النساء: 142]", "qawaid": ["العموم"], "tabi": ""}]}, {"id": 5364, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 340) في معنى: {والَّذِينَ يَمْكُرُونَ السَّيِّئاتِ} سوى قول قتادة، وابن زيد.", "mawaqif": []}], "12": [{"id": 5366, "kinds": "نقد،بيان،تعليق،نقل", "text": "بيَّن ابنُ عطية (7/ 209) أن المَخْر: هو الصوت الذي يحدث من جري السفينة بالريح. ثم علَّق بقوله: «وعبَّر المفسرون عن هذه بعبارات لا تختص باللفظة». وذكر قول قتادة، ثم نقل عن مجاهد أن المعنى: الريح تمخر السفن، ولا تمخر الريح من السفن إلا الفلك العظام. ثم استدرك قائلًا: «والصواب: أن تكون الفلك هي الماخرة، لا الممخورة».", "mawaqif": [{"taliq": 5366, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 209", "qawl": "", "nass": "وعبر المفسرون عن هذه بعبارات لا تختص باللفظة", "qawaid": [], "tabi": ""}]}], "13": [{"id": 5367, "kinds": "توجيه،نقل", "text": "نقل ابنُ عطية (7/ 210) قولًا ولم ينسبه: أنّ الأجل المسمى: آماد الليل وآماد النهار. ثم وجَّهه بقوله: «فـ {أجل} على هذا: اسم جنس».", "mawaqif": [{"taliq": 5367, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 210", "qawl": "", "nass": "ف {أجل} على هذا: اسم جنس", "qawaid": [], "tabi": ""}]}, {"id": 5368, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 349 - 350) في معنى: {ما يَمْلِكُونَ مِن قِطْمِيرٍ} سوى قول ابن عباس من طريق علي بن أبي طلحة وما في معناه.", "mawaqif": []}], "18": [{"id": 5370, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 355) في معنى: {إنّما تُنْذِرُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالغَيْبِ} سوى قول قتادة.", "mawaqif": []}], "19": [{"id": 5371, "kinds": "ترجيح،نقد،نقل", "text": "ذكر ابنُ جرير (19/ 356 - 357) قول ابن عباس أن الحَرور بالليل، والسَّموم بالنهار، ونسبه لرؤبة بن العجاج، ثم قال: «وأما أبو عبيدة فإنه قال: الحَرور في هذا الموضع بالنهار مع الشمس. وأما الفراء فإنه كان يقول: الحَرور يكون بالليل والنهار، والسَّموم لا يكون بالليل، إنما يكون بالنهار». ثم رجَّح قول الفراء أن الحَرور مطلقًا يكون بالليل والنهار، غير أنه رجَّح قول أبي عبيدة في تفسير الحَرور في هذا الموطن خاصة مستندًا إلى الدلالة العقلية قائلًا: «والصواب في ذلك عندنا: أنّ الحَرور يكون بالليل والنهار، غير أنه يكون في هذا الموضع بأن يكون كما قال أبو عبيدة أشبه مع الشمس؛ لأن الظل إنما يكون في يومِ شمسٍ، فذلك يدل على أنه أريد بالحَرور: الذي يوجد في حال وجود الظِّلّ».\nورجَّح ابنُ عطية (7/ 213) قول الفراء، فقال: «وإنما الأمر كما حكى الفراء وغيره: أن السموم تختص بالنهار، والحَرور يقال في حرِّ الليل وفي حرِّ النهار». ولم يذكر مستندًا، وانتقد قول رؤبة بن العجّاج قائلًا: «وليس كما قال».", "mawaqif": [{"taliq": 5371, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 356 - 357", "qawl": "ابن عباس", "nass": "وأما أبو عبيدة فإنه قال: الحرور في هذا الموضع بالنهار مع الشمس. وأما الفراء فإنه كان يقول: الحرور يكون بالليل والنهار، والسموم لا يكون بالليل، إنما يكون بالنهار", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5371, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 213", "qawl": "الفراء", "nass": "وإنما الأمر كما حكى الفراء وغيره: أن السموم تختص بالنهار، والحرور يقال في حر الليل وفي حر النهار", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5372, "kinds": "توجيه،نقل", "text": "ذكر ابنُ جرير (19/ 356) قول السدي ومقاتل، ولم ينسبه لأحد: أن {الظل}: الجنة، و {الحرور}: النار. ثم وجَّهه بقوله: «كأن معناه عندهم: ولا تستوي الجنة ولا النار».", "mawaqif": [{"taliq": 5372, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 356", "qawl": "السدي ومقاتل", "nass": "كأن معناه عندهم: ولا تستوي الجنة ولا النار", "qawaid": [], "tabi": ""}]}], "25": [{"id": 5373, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 361) في معنى: {بِالبَيِّناتِ وبِالزُّبُرِ} سوى قول قتادة.", "mawaqif": []}], "27": [{"id": 5374, "kinds": "توجيه،تعليق،نقل", "text": "علَّق ابنُ عطية (7/ 216) على قول ابن عباس بقوله: «ويؤيد هذا اطِّراد ذكر هذه الألوان فيما بعد». وذكر احتمالًا آخر، فقال: «ويحتمل: أن يريد الأنواع». ووجَّهه بقوله: «والمعتبر فيه -على هذا التأويل- أكثر عددًا».", "mawaqif": [{"taliq": 5374, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 216", "qawl": "ابن عباس", "nass": "ويؤيد هذا اطراد ذكر هذه الألوان فيما بعد", "qawaid": [], "tabi": ""}]}, {"id": 5375, "kinds": "نقد،نقل", "text": "حكى ابنُ عطية (7/ 216) عن أبي عبيدة في بعض كتبه: «أنه يقال: {جُدَدٌ} في معنى: جديد». ثم استدرك عليه قائلًا: «ولا مدخل لمعنى الجديد في هذه الآية».", "mawaqif": [{"taliq": 5375, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "حكى", "kind": "نقل", "ref": "7/ 216", "qawl": "", "nass": "أنه يقال: {جدد} في معنى: جديد", "qawaid": [], "tabi": ""}]}], "28": [{"id": 5377, "kinds": "ترجيح،نقد،بيان،نقل", "text": "نقل ابنُ عطية (7/ 216) عن بعض المفسرين قولهم: الخشية رأس العلم. ثم انتقدهم قائلًا: «وهذه عبارة وعْظِيَّةٌ، لا تثبت عند النقد». ثم رجَّح (7/ 217) قائلًا: «بل الصحيح المطرد أن يُقال: العلم رأس الخشية وسببها، والذي ورد عن النبي صلى الله عليه وسلم أنه قال: «خشية الله رأس كل حكمة». وقال: «رأس الحكمة مخافة الله». فهذا هو الكلام المنير».\nوبيَّن ابنُ القيم (2/ 348) دلالة الحصر في الآية، فقال: «وقوله تعالى: {إنَّما يَخْشى اللَّهَ مِن عِبادِهِ العُلَماءُ} يقتضي الحصر من الطرفين أن لا يخشاه إلا العلماء، ولا يكون عالمًا إلا من يخشاه، فلا يخشاه إلا عالم، وما من عالم إلا وهو يخشاه، فإذا انتفى العلم انتفت الخشية، وإذا انتفت الخشية دلَّتْ على انتفاء العلم، لكن وقع الغلط في مسمى العلم اللازم للخشية حيث يظن أنه يحصل بدونها، وهذا ممتنع؛ فإنه ليس في الطبيعة أن لا يخشى النار والأسد والعدو مَن هو عالم بها مواجه لها، وأنه لا يخشى الموت مَن ألقى نفسه مِن شاهق، ونحو ذلك، فأمنُه في هذه المواطن دليلُ عدم علمه، وأحسن أحواله أن يكون معه ظنٌّ لا يصل إلى رتبة العلم اليقيني».", "mawaqif": [{"taliq": 5377, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 216", "qawl": "", "nass": "وهذه عبارة وعظية، لا تثبت عند النقد", "qawaid": [], "tabi": ""}, {"taliq": 5377, "mi": 0, "aya": 28, "alam": "ابن القيم", "fil": "بين", "kind": "بيان", "ref": "2/ 348", "qawl": "", "nass": "وقوله تعالى: {إنما يخشى الله من عباده العلماء} يقتضي الحصر من الطرفين أن لا يخشاه إلا العلماء، ولا يكون عالما إلا من يخشاه، فلا يخشاه إلا عالم، وما من عالم إلا وهو يخشاه، فإذا انتفى العلم انتفت الخشية، وإذا انتفت الخشية دلت على انتفاء العلم، لكن وقع الغلط في مسمى العلم اللازم للخشية حيث يظن أنه يحصل بدونها، وهذا ممتنع؛ فإنه ليس في الطبيعة أن لا يخشى النار والأسد والعدو من هو عالم بها مواجه لها، وأنه لا يخشى الموت من ألقى نفسه من شاهق، ونحو ذلك، فأمنه في هذه المواطن دليل عدم علمه، وأحسن أحواله أن يكون معه ظن لا يصل إلى رتبة العلم اليقيني", "qawaid": [], "tabi": ""}]}, {"id": 5378, "kinds": "غيره", "text": "قال ابنُ تيمية (5/ 306): «وقوله تعالى: {إنَّما يَخْشى اللَّهَ مِن عِبادِهِ العُلَماءُ} يقتضي: أنّ كل من خشي الله فهو عالم؛ فإنه لا يخشاه إلا عالم. ويقتضي أيضًا: أنّ العالم من يخشى الله كما قال السلف. قال ابن مسعود: كفى بخشية الله علمًا، وكفى بالاغترار جهلًا».", "mawaqif": [{"taliq": 5378, "mi": 0, "aya": 28, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "5/ 306", "qawl": "", "nass": "وقوله تعالى: {إنما يخشى الله من عباده العلماء} يقتضي: أن كل من خشي الله فهو عالم؛ فإنه لا يخشاه إلا عالم. ويقتضي أيضا: أن العالم من يخشى الله كما قال السلف. قال ابن مسعود: كفى بخشية الله علما، وكفى بالاغترار جهلا", "qawaid": [], "tabi": ""}]}], "30": [{"id": 5379, "kinds": "توجيه،نقل", "text": "نقل ابنُ عطية (7/ 218) عن فرقة في معنى قوله تعالى: {ويَزِيدَهُمْ مِن فَضْلِهِ} أنه: تضعيف الحسنات من العشر إلى السبعمائة، ثم وجَّهه بقوله: «وتوفية الأجور -على هذا- هي المجازاة مقابلة».", "mawaqif": [{"taliq": 5379, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 218", "qawl": "", "nass": "وتوفية الأجور -على هذا- هي المجازاة مقابلة", "qawaid": [], "tabi": ""}]}], "32": [{"id": 5380, "kinds": "توجيه،نقل", "text": "وجَّه ابنُ عطية (7/ 219) قول ابن عباس: أنّ {الذين اصطفينا} يراد بهم: أمة محمد صلى الله عليه وسلم. بقوله: «وكأن اللفظ يحتمل أن يريد جميع المؤمنين مِن كل أمَّة، إلا أن عبارة توريث الكتاب لم تكن إلا لأمة محمد صلى الله عليه وسلم، والأُوَل لم يُوَرَّثوه».\nونقل ابنُ عطية (7/ 221) في الآية قولًا عن فرقة أن معنى «قوله تعالى: {الَّذِينَ اصْطَفَيْنا}: هم الأنبياء، والظالم لنفسه منهم من وقع في صغيرة». ثم انتقدهم قائلًا: «وهذا قول مردود مِن غير ما وجْه».", "mawaqif": [{"taliq": 5380, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 219", "qawl": "ابن عباس", "nass": "وكأن اللفظ يحتمل أن يريد جميع المؤمنين من كل أمة، إلا أن عبارة توريث الكتاب لم تكن إلا لأمة محمد صلى الله عليه وسلم، والأول لم يورثوه", "qawaid": [], "tabi": ""}, {"taliq": 5380, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 221", "qawl": "", "nass": "قوله تعالى: {الذين اصطفينا}: هم الأنبياء، والظالم لنفسه منهم من وقع في صغيرة", "qawaid": [], "tabi": ""}]}, {"id": 5382, "kinds": "نقل", "text": "نقل ابنُ عطية (7/ 220) أقوالًا أخرى في معنى الآية، فقال: «وقال سهل بن عبد الله: السابق العالم، والمقتصد المتعلم، والظالم الجاهل. وقال ذو النون: الظالم الذاكر لله بلسانه فقط، والمقتصد الذاكرُ بقلبه، والسابق الذي لا ينساه. وقال الأنطاكي: الظالم صاحب الأقوال، والمقتصد صاحب الأفعال، والسابق صاحب الأحوال».", "mawaqif": [{"taliq": 5382, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 220", "qawl": "", "nass": "وقال سهل بن عبد الله: السابق العالم، والمقتصد المتعلم، والظالم الجاهل. وقال ذو النون: الظالم الذاكر لله بلسانه فقط، والمقتصد الذاكر بقلبه، والسابق الذي لا ينساه. وقال الأنطاكي: الظالم صاحب الأقوال، والمقتصد صاحب الأفعال، والسابق صاحب الأحوال", "qawaid": [], "tabi": ""}]}], "40": [{"id": 5386, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 390) في معنى: {قُلْ أرَأَيْتُمْ شُرَكاءَكُمُ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ … } سوى قول قتادة.", "mawaqif": []}], "41": [{"id": 5387, "kinds": "نقد،توجيه", "text": "انتقد ابن كثير (11/ 338) هذا الحديث قائلًا: «والظاهر أن هذا الحديث ليس بمرفوع، بل من الإسرائيليات المنكرة، فإن موسى عليه السلام أجلُّ مِن أن يُجَوِّز على الله? النوم، وقد أخبر الله تعالى في كتابه العزيز بأنه: {الحَيُّ القَيُّومُ لا تَأْخُذُهُ سِنَةٌ ولا نَوْمٌ لَهُ ما فِي السَّمَواتِ وما فِي الأرْضِ} [البقرة: 255]، وثبت في الصحيحين عن أبي موسى الأشعري? قال: قال رسول الله صلى الله عليه وسلم: «إنّ الله لا ينام، ولا ينبغي له أن ينام، يخفض القسط ويرفعه، يرفع إليه عمل الليل قبل النهار، وعمل النهار قبل الليل، حجابه النور أو النار، لو كشفه لأحرقت سُبُحات وجْهه ما انتهى إليه بصره من خلقه»».", "mawaqif": [{"taliq": 5387, "mi": 0, "aya": 41, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "11/ 338", "qawl": "", "nass": "والظاهر أن هذا الحديث ليس بمرفوع، بل من الإسرائيليات المنكرة، فإن موسى عليه السلام أجل من أن يجوز على الله? النوم، وقد أخبر الله تعالى في كتابه العزيز بأنه: {الحي القيوم لا تأخذه سنة ولا نوم له ما في السموات وما في الأرض} [البقرة: 255]، وثبت في الصحيحين عن أبي موسى الأشعري? قال: قال رسول الله صلى الله عليه وسلم: «إن الله لا ينام، ولا ينبغي له أن ينام، يخفض القسط ويرفعه، يرفع إليه عمل الليل قبل النهار، وعمل النهار قبل الليل، حجابه النور أو النار، لو كشفه لأحرقت سبحات وجهه ما انتهى إليه بصره من خلقه»", "qawaid": [], "tabi": ""}]}, {"id": 5388, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (11/ 339) هذا الأثر من رواية ابن جرير بسنده عن ابن بشار، عن عبد الرحمن، عن سفيان، عن الأعمش، عن أبي وائل، عن ابن مسعود، ثم علَّق عليه بقوله: «وهذا إسناد صحيح إلى كعب وإلى ابن مسعود».", "mawaqif": [{"taliq": 5388, "mi": 0, "aya": 41, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 339", "qawl": "", "nass": "وهذا إسناد صحيح إلى كعب وإلى ابن مسعود", "qawaid": [], "tabi": ""}]}, {"id": 5389, "kinds": "تعليق", "text": "علَّق ابنُ عطية (7/ 227) على قول ابن مسعود بقوله: «ويظهر من قول ابن مسعود أن السماء لا تدور، وإنما تجري فيها الكواكب».", "mawaqif": [{"taliq": 5389, "mi": 0, "aya": 41, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 227", "qawl": "ابن مسعود", "nass": "ويظهر من قول ابن مسعود أن السماء لا تدور، وإنما تجري فيها الكواكب", "qawaid": [], "tabi": ""}]}], "43": [{"id": 5390, "kinds": "تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 393) في قوله تعالى: {اسْتِكْبارًا فِي الأَرْضِ ومَكْرَ السَّيِّء} أن المَكْر أُضيف إلى السِّيِّئ، «والسيء من نعت المكر، كما قيل: {إنَّ هَذا لَهُوَ حَقُّ اليَقِينِ} [الواقعة: 95]». ثم ذكر قراءة ابن مسعود، ثم علَّق عليها بقوله: «وفي ذلك تحقيق القول الذي قلناه مِن أن السيئ في المعنى من نعت المكر».", "mawaqif": [{"taliq": 5390, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 393", "qawl": "", "nass": "والسيء من نعت المكر، كما قيل: {إن هذا لهو حق اليقين} [الواقعة: 95]", "qawaid": [], "tabi": ""}]}]}, "athar": {"63874": {"num": 63874, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {إلَيْهِ يَصْعَدُ الكَلِمُ الطَّيِّبُ والعَمَلُ الصّالِحُ يَرْفَعُهُ} قال: لا يقبل الله قولًا إلا بعمل، مَن قال وأحسن العمل قَبِل الله منه."}, "63875": {"num": 63875, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {إلَيْهِ يَصْعَدُ الكَلِمُ الطَّيِّبُ والعَمَلُ الصّالِحُ يَرْفَعُهُ}، قال: لا يُقبَل قولٌ إلا بعمل."}, "63876": {"num": 63876, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {والعَمَلُ الصّالِحُ يَرْفَعُهُ}، قال: يرفع اللهُ العملَ لصاحبه."}, "64132": {"num": 64132, "aya": 32, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {ذَلِكَ هُوَ الفَضْلُ الكَبِيرُ}، قال: ذاك مِن نعمة الله."}, "63885": {"num": 63885, "aya": 10, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {والَّذِينَ يَمْكُرُونَ السَّيِّئاتِ} قال: هم أصحاب الرياء. وفي قوله: {ومَكْرُ أُولَئِكَ هُوَ يَبُورُ} قال: الرياء."}, "63887": {"num": 63887, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {والَّذِينَ يَمْكُرُونَ السَّيِّئاتِ} قال: يعملون السيئات، {ومَكْرُ أُولَئِكَ هُوَ يَبُورُ} قال: هو يَفْسُد."}, "64148": {"num": 64148, "aya": 34, "qail": "شمر بن عطية", "tabaqa": "", "bab": "", "text": "عن شِمْر بن عطية، قال: قال رسول الله صلى الله عليه وسلم حيث دخلوا الجنة قالوا: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ} قال: «كان حُزنهم همَّ الخُبز»."}, "64150": {"num": 64150, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قول أهل الجنة حين دخلوا الجنة: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ}، قال: هم قوم كانوا في الدنيا يخافون الله، ويجتهدون له في العبادة سِرًّا وعلانية، وفي قلوبهم حَزَن مِن ذنوبٍ قد سلفت منهم، فهم خائفون ألّا يُتقبل منهم هذا الاجتهاد؛ من الذنوب التي قد سلفت منهم، فعندها قالوا: {وقالُوا الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ إنَّ رَبَّنا لَغَفُورٌ شَكُورٌ} غفر لنا العظيم، وشكر لنا القليل من أعمالنا."}, "64151": {"num": 64151, "aya": 34, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي الجوزاء- في قوله: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ}، قال: حَزن النار."}, "63898": {"num": 63898, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، عن النبي صلى الله عليه وسلم، قال: «كان في بني إسرائيل ملِكان أخوان على مدينتين، وكان أحدُهما بارًّا برَحِمه، عادلًا على رَعِيَّته، وكان الآخر عاقًّا برَحِمه، جائرًا على رعيّته، وكان في عصرهما نبيٌّ، فأوحى الله إلى ذلك النبي: أنه قد بقي مِن عُمر هذا البارّ ثلاث سنين، وبقي من عمر هذا العاقّ ثلاثون سنة. فأخبر النبيُّ رعيةَ هذا ورعيةَ هذا، فأحزن ذلك رعية العادل، وأحزن ذلك رعية الجائر، ففرّقوا بين الأطفال والأمهات، وتركوا الطعام والشراب، وخرجوا إلى الصحراء يدعون الله أن يمتِّعهم بالعادل، ويزيل عنهم الجائر، فأقاموا ثلاثًا، فأوحى الله إلى ذلك النبي: أنْ أخْبِر عبادي أني قد رحمتُهم، وأجبتُ دعاءَهم، فجعلتُ ما بقي من عُمر هذا البارّ لذلك الجائر، وما بقي من عُمر الجائر لهذا البار. فرجعوا إلى بيوتهم، ومات العاقّ لتمام ثلاث سنين، وبقي العادل فيهم ثلاثين سنة». ثم تلا رسول الله صلى الله عليه وسلم: {وما يُعَمَّرُ مِن مُعَمَّرٍ ولا يُنْقَصُ مِن عُمُرِهِ إلّا فِي كِتابٍ إنَّ ذَلِكَ عَلى اللَّهِ يَسِيرٌ}."}, "63899": {"num": 63899, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {وما يُعَمَّرُ مِن مُعَمَّرٍ} الآية، يقول: ليس أحدٌ قضيت له طول العُمر والحياة إلا وهو بالِغٌ ما قدَّرتُ له من العُمر، وقد قضيت له ذلك، فإنما ينتهي له الكتاب الذي قدَّرتُ له، لا يُزاد عليه، وليس أحد قضيتُ له أنه قصير العمر والحياة ببالغٍ العمر، ولكن ينتهي إلى الكتاب الذي كُتِب له، فذلك قوله: {ولا يُنْقَصُ مِن عُمُرِهِ إلّا فِي كِتابٍ} يقول: كل ذلك في كتاب عنده."}, "63900": {"num": 63900, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {وما يُعَمَّرُ مِن مُعَمَّرٍ ولا يُنْقَصُ مِن عُمُرِهِ}، قال: يُكتب نقص شهر، نقص شهران، نقص ثلاثة أشهر، نقص سنة، نقص سنتان، نقص ثلاث سنين، حتى يأتي على أجله فيموت."}, "64158": {"num": 64158, "aya": 34, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يحيى بن المختار- {وإذا خاطَبَهُمُ الجاهِلُونَ قالُوا سَلامًا} [الفرقان: 63]، قال: إنّ المؤمنين قوم ذُلُل، ذلّت -واللهِ- الأسماعُ والأبصار والجوارح، حتى يحسبهم الجاهل مرضى، وما بالقوم مِن مرض، وإنهم لأصحة القلوب، ولكن دخلهم من الخوف ما لم يدخل غيرَهم، ومنعهم من الدنيا علمُهم بالآخرة، فقالوا: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ}. واللهِ، ما حُزنهم حزن الدنيا، ولا تعاظَم في أنفسهم ما طلبوا به الجنة، أبكاهم الخوفُ مِن النار، وأنه مَن لا يَتَعَزَّ بعزاء الله يقْطع نفسه على الدنيا حسرات، ومَن لم يرَ لله عليه نعمة إلا في مطعم أو مشرب فقد قلَّ علمه، وحضر عذابه."}, "64159": {"num": 64159, "aya": 34, "qail": "عطية العوفي", "tabaqa": "تابعي", "bab": "", "text": "عن عطية [العوفي]-من طريق ابن إدريس، عن أبيه- في قوله: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ}، قال: الموت."}, "64161": {"num": 64161, "aya": 34, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {الَّذِي أذْهَبَ عَنّا الحَزَنَ}، قال: كانوا يعملون في الدنيا، ويحزَنون، وينصبون."}, "64162": {"num": 64162, "aya": 34, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ} حزن الموت."}, "64164": {"num": 64164, "aya": 34, "qail": "شمر بن عطية", "tabaqa": "", "bab": "", "text": "عن شِمْر بن عطية -من طريق حفص بن حميد- في قوله: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ}، قال: الجوع."}, "64165": {"num": 64165, "aya": 34, "qail": "شمر بن عطية", "tabaqa": "", "bab": "", "text": "عن شِمْر بن عطية -من طريق حفص بن حميد- في قوله: {الحَمْدُ لِلَّهِ الَّذِي أذْهَبَ عَنّا الحَزَنَ}، قال: حَزَن الطعام."}, "64169": {"num": 64169, "aya": 34, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {إنَّ رَبَّنا لَغَفُورٌ شَكُورٌ}، يقول: غفور لذنوبهم، شكور لحسناتهم."}, "64170": {"num": 64170, "aya": 34, "qail": "شمر بن عطية", "tabaqa": "", "bab": "", "text": "عن شِمْر بن عطية -من طريق حفص بن حميد- في قوله: {إنَّ رَبَّنا لَغَفُورٌ شَكُورٌ}، قال: غفر لهم الذنوب التي عملوها، وشكر لهم الخيرَ الذي دلَّهم عليه فعملوا به، فأثابهم عليه."}, "63919": {"num": 63919, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {وما يُعَمَّرُ مِن مُعَمَّرٍ ولا يُنْقَصُ مِن عُمُرِهِ إلّا فِي كِتابٍ}، قال: ألا ترى الناس! يعيش الإنسانُ مائة سنة، وآخر يموت حين يُولد، فهذا هذا."}, "63920": {"num": 63920, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم، في قوله: {ولا يُنْقَصُ مِن عُمُرِهِ}، قال: ما لفظت الأرحام من الأولاد من غير تمام."}, "64196": {"num": 64196, "aya": 37, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، أنّ رسول الله صلى الله عليه وسلم قال: «العمر الذي أعذر الله تعالى فيه إلى ابن آدم: ستون سنة». يعني: {أوَلَمْ نُعَمِّرْكُمْ ما يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ}."}, "64197": {"num": 64197, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، أنّ النبي صلى الله عليه وسلم قال: «إذا كان يوم القيامة قيل: أين أبناء الستين؟ وهو العمر الذي قال الله: {أوَلَمْ نُعَمِّرْكُمْ ما يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ}»."}, "64199": {"num": 64199, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سفيان، عن ابن خُثيم، عن مجاهد- في قوله: {أوَلَمْ نُعَمِّرْكُمْ ما يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ}، قال: ستين سنة."}, "64200": {"num": 64200, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس -من طريق بشر بن المفضل، عن ابن خُثيم، عن مجاهد- يقول: العمر الذي أعذر الله إلى ابن آدم {أوَلَمْ نُعَمِّرْكُمْ ما يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ}: أربعون سنة."}, "64201": {"num": 64201, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس-من طريق مجاهد- {أوَلَمْ نُعَمِّرْكُمْ ما يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ}، قال: هو ست وأربعون سنة."}, "64202": {"num": 64202, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطاء- {أوَلَمْ نُعَمِّرْكُمْ ما يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وجاءَكُمُ النَّذِيرُ}، قال: نزلت تَعْيِيرًا لأبناء السبعين."}, "64075": {"num": 64075, "aya": 32, "qail": "عوف بن مالك", "tabaqa": "", "bab": "", "text": "عن عوف بن مالك، عن رسول الله صلى الله عليه وسلم، قال: «أُمَّتي ثلاثة أثلاث: فثلُث يدخلون الجنة بغير حساب، وثلُث يُحاسبون حسابًا يسيرًا ثم يدخلون الجنة، وثلث يُمَحّصون ويُكْسَفون، ثم تأتي الملائكة فيقولون: وجدناهم يقولون: لا إله إلا الله وحده. فيقول الله: أدخِلوهم الجنة بقولهم: لا إله إلا الله وحده. واحمِلوا خطاياهم على أهل التكذيب. وهي التي قال الله: {ولَيَحْمِلُنَّ أثْقالَهُمْ وأَثْقالًا مَعَ أثْقالِهِمْ} [العنكبوت: 13]، وتصديقًا في التي ذكر في الملائكة؛ قال الله تعالى: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} فجعلهم ثلاثة أفواج؛ {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ} فهذا الذي يُكسَف ويمحّص، {ومِنهُمْ مُقْتَصِدٌ} وهو الذي يُحاسب حسابًا يسيرًا، {ومنهم سابق بالخيرات} فهو الذي يَلِج الجنة بغير حسابٍ ولا عذاب بإذن الله، يدخلونها جميعًا لم يُفَرَّقْ بينهم، {يُحَلَّوْنَ فِيها مِن أساوِرَ مِن ذَهَبٍ} إلى قوله: {لُغُوبٌ}»."}, "64203": {"num": 64203, "aya": 37, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأجدع الهمداني -من طريق الشعبي- أنّه كان يقول: إذا بلغ أحدكم أربعين سنة فليأخذ حِذْرَه من الله."}, "64211": {"num": 64211, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عبد الله بن عطية، عمَّن حدَّثه- {وجاءَكُمُ النَّذِيرُ}، قال: الشَّيْبُ."}, "64084": {"num": 64084, "aya": 32, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر، عن النبي صلى الله عليه وسلم، في قوله: {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ}، قال: «الكافر»."}, "64085": {"num": 64085, "aya": 32, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق شقيق- قال: هذه الأمة ثلاثة أثلاث يوم القيامة: ثلُث يدخلون الجنة بغير حساب، وثلُث يحاسبون حسابًا يسيرًا، وثلُث يجيئون بذنوبٍ عظام إلا أنهم لم يشركوا، فيقول الرب: أدخِلوا هؤلاء في سعة رحمتي. ثم قرأ: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} الآية."}, "64216": {"num": 64216, "aya": 37, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم- من طريق ابن وهب- في قوله: {وجاءَكُمُ النَّذِيرُ}، قال: محمد صلى الله عليه وسلم. وقرأ: {هَذا نَذِيرٌ مِنَ النُّذُرِ الأُولى} [النجم: 56]."}, "64091": {"num": 64091, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس - من طريق عطاء- قال: السابق بالخيرات يدخل الجنة بغير حساب، والمقتصد يدخل الجنة برحمة الله، والظالم لنفسه وأصحاب الأعراف يدخلون الجنة بشفاعة محمد صلى الله عليه وسلم."}, "64092": {"num": 64092, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- في قوله: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} الآية، قال: هي مثل التى في الواقعة [8 - 10]: {فَأَصْحابُ المَيْمَنَةِ ما أصْحابُ المَيْمَنَةِ * وأَصْحابُ المَشْأَمَةِ ما أصْحابُ المَشْأَمَةِ * والسّابِقُونَ السّابِقُونَ}؛ صنفان ناجيان، وصنف هالك."}, "64093": {"num": 64093, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} الآية، قال: جعل الله أهلَ الإيمان على ثلاثة منازل، كقوله: {وأَصْحابُ الشِّمالِ ما أصْحابُ الشِّمالِ} [الواقعة: 41]، {وأَصْحابُ اليَمِينِ ما أصْحابُ اليَمِينِ} [الواقعة: 27]، {والسّابِقُونَ السّابِقُونَ * أُولَئِكَ المُقَرَّبُونَ} [الواقعة: 10 - 11] فهم على هذا المثال."}, "64094": {"num": 64094, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عمرو بن دينار- في قوله: {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ} الآية، قال: هو الكافر، والمقتصد: أصحاب اليمين."}, "64095": {"num": 64095, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق على- في قوله: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا}، قال: هم أمة محمد صلى الله عليه وسلم، ورَّثهم اللهُ كلَّ كتاب أُنزل، فظالمهم مغفور له، ومقتصدهم يُحاسب حسابًا يسيرًا، وسابقهم يدخل الجنة بغير حساب."}, "64096": {"num": 64096, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ ومِنهُمْ مُقْتَصِدٌ ومِنهُمْ سابِقٌ بِالخَيْراتِ بِإذْنِ اللَّهِ}، قال: اثنان في الجنة، وواحد في النار."}, "64097": {"num": 64097, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ ومِنهُمْ مُقْتَصِدٌ ومِنهُمْ سابِقٌ بِالخَيْراتِ بِإذْنِ اللَّهِ} السابق: المؤمن المخلص. والمقتصد: المرائي. والظالم: الكافر نعمة الله غير الجاحد لها. لأنه حكم للثلاثة بدخول الجنة، فقال: {جَنّاتُ عَدْنٍ يَدْخُلُونَها}."}, "64099": {"num": 64099, "aya": 32, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، أنّه سأل كعبًا عن قوله: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} الآية. قال: نجَوْا كلهم. ثم قال: تحاكَّت مناكبهم، وربِّ الكعبة، ثم أُعطوا الفضل بأعمالهم."}, "64100": {"num": 64100, "aya": 32, "qail": "كعب الأحبار", "tabaqa": "تابعي", "bab": "", "text": "عن كعب الأحبار -من طريق عبد الله بن الحارث- أنّه تلا هذه الآية: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} إلى قوله: {لغوب}. قال: دخلوها، وربِّ الكعبة. وفي لفظٍ قال: كلهم في الجنة؛ ألا ترى على أثره: {والَّذِينَ كَفَرُوا لَهُمْ نارُ جَهَنَّمَ} [فاطر: 36]؟ فهؤلاء أهل النار. ="}, "64102": {"num": 64102, "aya": 32, "qail": "كعب الأحبار", "tabaqa": "تابعي", "bab": "", "text": "عن كعب الأحبار -من طريق عبد الله بن الحارث- في قوله: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} إلى قوله: {جَنّاتُ عَدْنٍ يَدْخُلُونَها}، قال: دخلوها، وربِّ الكعبة. ="}, "64104": {"num": 64104, "aya": 32, "qail": "كعب الأحبار", "tabaqa": "تابعي", "bab": "", "text": "قال كعب الأحبار -من طريق صالح أبي الخليل-: يلومني أحبارُ بني إسرائيل أنِّي دخلتُ في أمةٍ فرَّقهم الله، ثم جمعهم، ثم أدخلهم الجنة جميعًا! ثم تلا هذه الآية: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا} حتى بلغ: {جَنّاتُ عَدْنٍ يَدْخُلُونَها}. قال: فأدخلهم اللهُ الجنةَ جميعًا."}, "63852": {"num": 63852, "aya": 10, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {مَن كانَ يُرِيدُ العِزَّةَ} قال: بعبادة الأوثان؛ {فَلِلَّهِ العِزَّةُ جَمِيعًا}."}, "63854": {"num": 63854, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {مَن كانَ يُرِيدُ العِزَّةَ فَلِلَّهِ العِزَّةُ جَمِيعًا}، قال: فلْيَتَعَزَّز بطاعة الله."}, "64110": {"num": 64110, "aya": 32, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر: {أوْرَثْنا} أعطينا؛ لأن الميراث عطاء."}, "64111": {"num": 64111, "aya": 32, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ} قال: هم أصحاب المشأمة، {ومِنهُمْ مُقْتَصِدٌ} قال: هم أصحاب الميمنة، {ومِنهُمْ سابِقٌ بِالخَيْراتِ بِإذْنِ اللَّهِ} قال: هم السابقون من الناس كلهم."}, "64112": {"num": 64112, "aya": 32, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق جابر- في قوله تعالى: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا}، قال: هذا مثل التي في الواقعة [7]: {وكنتم أزواجا ثلاثة}."}, "64113": {"num": 64113, "aya": 32, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عاصم بن حكيم- قال في قوله: {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ}: هو الجاحد، والمنافق."}, "64115": {"num": 64115, "aya": 32, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق قرة- في قوله: {ثُمَّ أوْرَثْنا الكِتابَ الَّذِينَ اصْطَفَيْنا مِن عِبادِنا فَمِنهُمْ ظالِمٌ لِنَفْسِهِ} قال: سقط هذا، {ومِنهُمْ مُقْتَصِدٌ ومِنهُمْ سابِقٌ بِالخَيْراتِ بِإذْنِ اللَّهِ} قال: سبق هذا بالخيرات، وهذا مقتصد على أثره."}, "64116": {"num": 64116, "aya": 32, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جويبر ="}, "63864": {"num": 63864, "aya": 10, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {إلَيْهِ يَصْعَدُ الكَلِمُ الطَّيِّبُ والعَمَلُ الصّالِحُ يَرْفَعُهُ}، قال: العمل الصالح هو الذي يرفع الكلامَ الطيب."}, "64121": {"num": 64121, "aya": 32, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة -من طريق معمر- في قوله تعالى: {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ}، قال: هو المنافق."}, "64123": {"num": 64123, "aya": 32, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ} قال: هذا المنافق، {ومِنهُمْ مُقْتَصِدٌ} قال: هذا صاحب اليمين، {ومنهم سابق بالخيرات} قال: هذا المقرّب. قال قتادة بن دعامة: كان الناس ثلاث منازل عند الموت، وثلاث منازل في الدنيا، وثلاث منازل في الآخرة، فأما الدنيا فكانوا [مؤمنًا، ومنافقًا، ومشركًا]، وأَمّا عند الموت فإن الله قال: {فَأَمّا إنْ كانَ مِنَ المُقَرَّبِينَ} الآية [الواقعة: 88]، {وأَمّا إنْ كانَ مِن أصْحابِ اليَمِينِ} الآية [الواقعة: 90]، {وأَمّا إنْ كانَ مِنَ المُكَذِّبِينَ الضّالِّينَ} الآية [الواقعة: 92]، وأَمّا الآخرة فكانوا أزواجًا ثلاثة: {فَأَصْحابُ المَيْمَنَةِ ما أصْحابُ المَيْمَنَةِ * وأَصْحابُ المَشْأَمَةِ ما أصْحابُ المَشْأَمَةِ * والسّابِقُونَ السّابِقُونَ} [الواقعة: 8 - 10]."}, "64124": {"num": 64124, "aya": 32, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق عثمان-: أن أصحاب اليمين هم الذين يُحاسبون حسابًا يسيرًا، وهو المقتصد في حديث أبي الدرداء عن النبي صلى الله عليه وسلم، وهم أصحاب المنزل الآخر في سورة الرحمن [62] حيث يقول: {ومِن دُونِهِما جَنَّتانِ} فوصفهما، ومنزل السابقين المنزل الآخر في سورة الرحمن [46] في قوله: {ولِمَن خافَ مَقامَ رَبِّهِ جَنَّتانِ} فوصفهما."}}, "n_athar": {"0": 11, "1": 20, "2": 14, "3": 5, "4": 3, "5": 9, "6": 7, "7": 4, "8": 18, "9": 6, "10": 41, "11": 31, "12": 15, "13": 22, "14": 4, "15": 2, "16": 3, "17": 3, "18": 20, "19": 9, "22": 5, "23": 4, "25": 6, "26": 3, "27": 12, "28": 25, "29": 6, "30": 9, "31": 3, "32": 60, "33": 8, "34": 30, "35": 10, "36": 10, "37": 27, "38": 2, "39": 3, "40": 4, "41": 16, "42": 5, "43": 16, "44": 4, "45": 6}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});